        return requireString('sku') || requireAmount('qty', 1) || requireAmount('unitPriceCents', 0);
      case 'removeItem':
        return requireString('sku');
      case 'pay':
        return requireAmount('amountCents', 0);
      case 'ship':
        return requireString('carrier') || requireString('tracking');
      case 'cancel':
        return requireString('reason');
      case 'refund':
