   *
   * @param {object} command Command being applied.
   * @returns {string} The state after the effect.
   */
  #effect(command) {
    switch (command.type) {
      case 'addItem':
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        return 'created';
      case 'removeItem':
        this.#items.delete(command.sku);
        return 'created';
      case 'pay':
        this.#paidCents = command.amountCents;
        return 'paid';
      case 'pack':
        return 'packed';
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        return 'shipped';
      case 'deliver':
        this.#deliveredAt = command.at;
        return 'delivered';
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        return 'cancelled';
      case 'refund':
        this.#refundedCents += command.amountCents;
        return this.#refundedCents >= this.#paidCents ? 'refunded' : 'delivered';
      default:
        return this.#state;
    }
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPES.includes(command.type)) {
      throw new TypeError(`unknown command type: ${command.type}`);
    }
    if (typeof command.commandId !== 'string' || command.commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }
    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    const { type, commandId, at } = command;

    if (this.#results.has(commandId)) {
      return { ...this.#results.get(commandId), replayed: true };
    }

    const from = this.#state;
    let entryAt = at;
    let outcome;

    if (at < this.#clockMs) {
      entryAt = this.#clockMs;
      outcome = { code: 'CLOCK_REGRESSION', message: 'command time precedes the order clock' };
    } else {
      this.#clockMs = at;
      if (!allowedTypes(from).includes(type)) {
        outcome = { code: 'BAD_STATE', message: `${type} is not allowed while the order is ${from}` };
      } else {
        outcome = this.#validate(command) || this.#guard(command);
      }
